let data={};let role='customer';let section='dashboard';let token=sessionStorage.getItem('dobrosmena_token')||'';let authError='';
const $=s=>document.querySelector(s), esc=s=>String(s??'').replace(/[&<>"']/g,m=>({'&':'&amp;','<':'&lt;','>':'&gt;','"':'&quot;',"'":'&#039;'}[m]));
const money=n=>Number(n||0).toLocaleString('ru-RU',{maximumFractionDigits:0})+' ₽';
const dt=x=>new Date(x).toLocaleString('ru-RU',{dateStyle:'short',timeStyle:'short'});
const status=o=>`<span class="pill ${['replacement','incident','cancelled','blocked','disputed'].includes(o.status)?'danger':''}">${esc(o.status_label)}</span>`;
async function api(url,opt={}){
  const headers={...(opt.headers||{})};
  if(!(opt.body instanceof FormData)) headers['Content-Type']='application/json';
  if(token) headers.Authorization=`Bearer ${token}`;
  let r=await fetch(url,{...opt,headers}); let x={}; try{x=await r.json()}catch(e){}
  if(r.status===401){token='';sessionStorage.removeItem('dobrosmena_token');openAuth('login','Сессия закончилась. Войдите снова.');throw Error('Сессия закончилась.')}
  if(!r.ok)throw Object.assign(Error(x.detail||x.non_field_errors?.[0]||'Ошибка'),x); return x;
}
function roleLabel(r){return ({customer:'Заказчик',caregiver:'Исполнитель',admin:'Администратор'})[r]||r}
function goHome(e){if(e)e.preventDefault();renderPublicHome();window.scrollTo({top:0,behavior:'smooth'})}
function togglePublicMenu(){document.getElementById('publicLinks')?.classList.toggle('open')}
function toggleAccessibility(){let p=document.getElementById('accessPanel');if(!p){document.body.insertAdjacentHTML('beforeend',`<div class="access-panel" id="accessPanel"><h3>Режим для слабовидящих</h3><div class="access-grid"><button onclick="setAccess('large')">Крупный текст</button><button onclick="setAccess('contrast')">Высокий контраст</button><button onclick="setAccess('underline')">Подчёркивать ссылки</button><button onclick="setAccess('reset')">Обычный режим</button></div><p class="muted small">Настройки сохраняются на этом устройстве.</p></div>`);p=document.getElementById('accessPanel')}p.classList.toggle('open')}
function setAccess(mode){document.documentElement.dataset.access=mode==='reset'?'':mode;localStorage.setItem('dobrosmena-access',mode)}
function publicHeaderHtml(){return `<header class="public-header" id="publicHeader"><div class="public-nav public-wrap"><a class="brand" href="#home" onclick="goHome(event)"><span class="brand-mark">Д</span><span class="brand-name">Добросмена</span></a><nav class="public-links" id="publicLinks"><a href="#how">Как это работает</a><a href="#care">План ухода</a><a href="#specialists">Специалисты</a><a href="#safety">Безопасность</a></nav><div class="public-actions"><button class="access-button" onclick="toggleAccessibility()">Для слабовидящих</button>${token?`<button class="login-button" onclick="load()">Личный кабинет</button><button class="access-button" onclick="logout()">Выйти</button>`:`<button class="login-button" onclick="openAuth('login')">Войти</button>`}</div><button class="mobile-menu" onclick="togglePublicMenu()" aria-label="Открыть меню">☰</button></div></header>`}
function renderPublicHome(){
  const h=document.getElementById('publicHeader'); if(h)h.outerHTML=publicHeaderHtml();
  document.getElementById('app').innerHTML=`
  <section class="hero-public" id="home"><div class="wrap hero-grid"><div>
    <span class="eyebrow"><i class="eyebrow-dot"></i> Помощь рядом, когда она нужна</span>
    <h1>Помогаем организовать заботу о близком человеке дома</h1>
    <p class="lead">«Добросмена» помогает семье подобрать подходящего исполнителя, договориться о задачах, создать план ухода и спокойно организовать регулярные смены.</p>
    <div class="hero-actions"><button class="btn primary" onclick="openAuth('register')">Организовать помощь</button><a class="btn soft" href="#how">Посмотреть, как это работает</a></div>
    <div class="trust"><span><b>✓</b> Проверенные исполнители</span><span><b>✓</b> Понятный план ухода</span><span><b>✓</b> Поддержка и замена</span></div>
  </div><div class="hero-visual">
    <div class="hero-photo"><div class="hero-scene"><div class="scene-leaf"></div><div class="scene-leaf two"></div><div class="scene-person"></div></div></div>
    <div class="hero-card"><h3>Пример организации помощи</h3><div class="status"><span>Запрос семьи</span><span class="pill ok">Принят</span></div><div class="status"><span>Исполнитель</span><span class="pill ok">Подобран</span></div><div class="status"><span>План ухода</span><span class="pill">Актуален</span></div><div class="status"><span>Ближайшая смена</span><strong>Сегодня, 10:00</strong></div><div class="mini-progress" style="margin-top:13px"><i></i></div></div>
    <div class="hero-card bottom"><strong>Главное</strong><p class="muted small" style="margin:6px 0 0">Всё необходимое для ухода хранится в одном месте — у семьи и исполнителя.</p></div>
  </div></div></section>

  <section class="section" id="how"><div class="wrap"><div class="section-head"><h2>Как это работает</h2><p>Начните с нескольких простых вопросов. Дальше «Добросмена» помогает пройти путь от запроса семьи до подтверждённой смены.</p></div><div class="steps"><div class="step"><strong>01</strong><span>Кому нужна помощь</span><p class="small muted">Опишем ситуацию близкого человека.</p></div><div class="step"><strong>02</strong><span>Что нужно делать</span><p class="small muted">Задачи, ограничения и пожелания.</p></div><div class="step"><strong>03</strong><span>Когда и где</span><p class="small muted">График, район и длительность.</p></div><div class="step"><strong>04</strong><span>Подбор исполнителя</span><p class="small muted">Покажем подходящих специалистов.</p></div><div class="step"><strong>05</strong><span>Подтверждение и смена</span><p class="small muted">Оплата, выход и отчёт.</p></div></div></div></section>

  <section class="section alt"><div class="wrap"><div class="section-head"><h2>Вместо бесконечных звонков — одна система</h2><p>Мы строим сервис вокруг самой важной задачи семьи: организовать понятную и повторяемую помощь, а не просто найти человека на один раз.</p></div><div class="grid3"><div class="card"><div class="icon">👤</div><h3>Подходящий исполнитель</h3><p>Важна не только оценка, а соответствие вашему конкретному запросу.</p><div class="feature-list"><div><span class="check">✓</span> Личность и профиль проверены</div><div><span class="check">✓</span> Подходящий опыт и навыки</div><div><span class="check">✓</span> Доступность по графику</div></div></div><div class="card"><div class="icon">📋</div><h3>План ухода</h3><p>Все важные договорённости фиксируются до начала первой смены.</p><div class="feature-list"><div><span class="check">✓</span> Задачи и ограничения</div><div><span class="check">✓</span> История изменений</div><div><span class="check">✓</span> Контакты и правила действий</div></div></div><div class="card"><div class="icon">🔄</div><h3>Регулярность и замена</h3><p>Можно собрать команду из основного и резервного исполнителя.</p><div class="feature-list"><div><span class="check">✓</span> Повторяющиеся смены</div><div><span class="check">✓</span> Резервный исполнитель</div><div><span class="check">✓</span> Отчёт после смены</div></div></div></div></div></section>

  <section class="section" id="specialists"><div class="wrap"><div class="section-head"><h2>Специалисты под вашу задачу</h2><p>В карточке сразу видно, почему специалист подходит именно под запрос семьи.</p></div><div class="specialist-grid"><div class="card"><div class="person-card"><div class="avatar">АК</div><div><h3>Анна К.</h3><span class="pill ok">✓ Личность подтверждена</span></div></div><div class="chips"><span class="chip">6 лет опыта</span><span class="chip">Прогулки</span><span class="chip">Гигиена</span></div><div class="reason"><strong>Почему подходит</strong><p>Опыт регулярного сопровождения взрослых, доступна по будням.</p></div></div><div class="card"><div class="person-card"><div class="avatar">ЕС</div><div><h3>Елена С.</h3><span class="pill ok">✓ Профиль проверен</span></div></div><div class="chips"><span class="chip">8 лет опыта</span><span class="chip">Сопровождение</span><span class="chip">Питание</span></div><div class="reason"><strong>Почему подходит</strong><p>Подходит для спокойного регулярного сопровождения в течение смены.</p></div></div><div class="card"><div class="person-card"><div class="avatar">ИВ</div><div><h3>Ирина В.</h3><span class="pill ok">✓ Документы проверены</span></div></div><div class="chips"><span class="chip">5 лет опыта</span><span class="chip">Бытовая помощь</span><span class="chip">Резерв</span></div><div class="reason"><strong>Почему подходит</strong><p>Может подключаться как резервный исполнитель по согласованному графику.</p></div></div></div></div></section>

  <section class="section alt" id="care"><div class="wrap"><div class="section-head"><h2>План ухода — центр сервиса</h2><p>Перед первой сменой семья и сервис фиксируют, что именно должно происходить. Это помогает избежать недопонимания.</p></div><div class="care-grid"><div class="card"><div class="person-card"><div class="avatar">АП</div><div><h3>Алексей Петров</h3><span class="pill ok">План актуален</span></div></div><h3 style="margin-top:24px">Сегодня важно</h3><div class="checkgrid"><div class="checkitem">✓ Утренняя прогулка</div><div class="checkitem">✓ Завтрак по плану</div><div class="checkitem">✓ Сопровождение по дому</div><div class="checkitem">✓ Спокойное общение</div></div></div><div class="reason"><h3>Границы и безопасность</h3><div class="row"><span>Медицинские процедуры</span><span class="pill warn">Не входят</span></div><div class="row"><span>Интимная гигиена</span><span class="pill">По согласию</span></div><div class="row"><span>Новая задача</span><span class="pill">Нужна проверка</span></div><div class="row"><span>Экстренная ситуация</span><span class="pill ok">112 / 103</span></div></div></div></div></section>

  <section class="section warm" id="safety"><div class="wrap"><div class="section-head"><h2>Безопасность — часть сервиса</h2><p>«Добросмена» помогает организовать бытовой уход и сопровождение в пределах согласованного плана. Сервис не заменяет медицинскую помощь и экстренные службы.</p></div><div class="safety-grid"><div class="safety-note"><h3>Что проверяем</h3><div class="feature-list"><div><span class="check">✓</span> Личность и документы исполнителя</div><div><span class="check">✓</span> Навыки и заявленный опыт</div><div><span class="check">✓</span> Соответствие задачам заказа</div><div><span class="check">✓</span> Отзывы после выполненных смен</div></div></div><div class="safety-emergency"><h3>Если возникла экстренная ситуация</h3><p>При непосредственной угрозе жизни обращайтесь в экстренные службы.</p><button class="btn" onclick="window.location.href='tel:112'">112</button> <button class="btn" onclick="window.location.href='tel:103'">103</button></div></div></div></section>

  <section class="section"><div class="wrap"><div class="cta"><div><h2>Нужна помощь близкому человеку?</h2><p>Создайте аккаунт заказчика — после входа мы проведём вас через создание первого запроса.</p></div><button class="btn" onclick="openAuth('register')">Начать</button></div></div></section>
  <footer class="footer"><div class="public-wrap footer-grid"><div><div class="footer-brand">Добросмена</div><p>Инфраструктура для организации помощи близкому человеку дома.</p></div><div><strong>Сервис</strong><p><a href="#how">Как это работает</a><br><a href="#specialists">Специалисты</a><br><a href="#care">План ухода</a></p></div><div><strong>Важно</strong><p><a href="#safety">Безопасность</a><br><a href="#home">Главная</a></p></div></div></footer>`;
}
function openAuth(mode='login',message=''){
  authError=message||'';
  document.getElementById('modal').innerHTML=`<div class="modalbg" onclick="if(event.target===this)closeModal()"><div class="modal auth-modal"><button class="close" onclick="closeModal()">Закрыть</button><span class="eyebrow">Добросмена</span><h2 class="auth-title">${mode==='register'?'Создание аккаунта':'Вход в личный кабинет'}</h2><p class="muted">${mode==='register'?'Выберите роль и заполните данные для регистрации.':'Для входа используйте телефон или e-mail, указанные при регистрации.'}</p><div class="auth-switch"><button class="${mode==='login'?'active':''}" onclick="openAuth('login')">Войти</button><button class="${mode==='register'?'active':''}" onclick="openAuth('register')">Регистрация</button></div>${mode==='login'?loginFormHtml():registerFormHtml()}</div></div>`;
  if(mode==='register'){window.regRole=window.regRole||'customer';selectRegRole(window.regRole)}
  setTimeout(()=>document.getElementById(mode==='login'?'loginIdentifier':'regLastName')?.focus(),0)
}
function loginFormHtml(){return `${authError?`<div class="item" style="background:var(--warnbg);color:var(--warn)">${esc(authError)}</div>`:''}<label>Телефон или электронная почта<input id="loginIdentifier" class="input" autocomplete="username" placeholder="+7 900-000-00-02 или name@example.ru" oninput="if(/\\d/.test(this.value)) formatPhoneInput(this)"></label><label>Пароль<input id="loginPassword" class="input" type="password" autocomplete="current-password" placeholder="Пароль"></label><button class="btn primary full" onclick="login()">Войти</button><button class="linkbtn" onclick="openRecovery($('#loginIdentifier')?.value||'')">Забыли пароль?</button>`}
function registerFormHtml(){return `<div class="role-choice"><button id="roleCustomer" class="role-card active" onclick="selectRegRole('customer')"><b>Я заказчик</b><span>Хочу организовать помощь близкому человеку</span></button><button id="roleCaregiver" class="role-card" onclick="selectRegRole('caregiver')"><b>Я исполнитель</b><span>Хочу выполнять заказы и смены</span></button></div><label>Фамилия<input id="regLastName" class="input" autocomplete="family-name" placeholder="Иванов"></label><label>Имя<input id="regFirstName" class="input" autocomplete="given-name" placeholder="Иван"></label><label>Отчество<input id="regMiddleName" class="input" autocomplete="additional-name" placeholder="Иванович"></label><label>Номер телефона<input id="regPhone" class="input" autocomplete="tel" placeholder="+7 900-000-00-10" oninput="formatPhoneInput(this)"></label><label>Электронная почта<input id="regEmail" class="input" type="email" autocomplete="email" placeholder="name@example.ru"></label><label>Пароль<input id="regPassword" class="input" type="password" autocomplete="new-password" placeholder="Минимум 8 символов"></label><button class="btn primary full auth-register-submit" onclick="register()">Зарегистрироваться</button>`}
async function load(){if(!token){renderPublicHome();return}try{data=await api('/api/v1/bootstrap/');role=data.user.role;renderCabinetHeader();render()}catch(e){if(token)toast(e.message)}}
function renderCabinetHeader(){document.getElementById('publicHeader').outerHTML=`<header class="header-cabinet" id="publicHeader"><a class="brand" href="#" onclick="goHome(event)"><span class="brand-mark">Д</span><span>Добросмена</span></a><nav id="roles"></nav><div id="who" class="muted"></div><button class="btn" onclick="logout()">Выйти</button></header>`;document.querySelector('.top')?.classList.add('logged')}
function showAuth(message=''){openAuth('login',message)}
function formatPhoneInput(el){let d=el.value.replace(/\D/g,'');if(d.startsWith('8'))d='7'+d.slice(1);if(d.startsWith('7'))d=d.slice(1);d=d.slice(0,10);let out='+7';if(d.length)out+=' '+d.slice(0,3);if(d.length>3)out+='-'+d.slice(3,6);if(d.length>6)out+='-'+d.slice(6,8);if(d.length>8)out+='-'+d.slice(8,10);el.value=out;}
function openRecovery(identifier=''){document.getElementById('modal').innerHTML=`<div class="modalbg" onclick="if(event.target===this)closeModal()"><div class="modal recovery-modal"><button class="close" onclick="closeModal()">Закрыть</button><span class="eyebrow">Восстановление аккаунта</span><h2>Не помните пароль?</h2><p class="muted">Введите телефон или электронную почту, с которыми зарегистрирован аккаунт.</p><label>Телефон или электронная почта<input id="recoveryIdentifier" class="input" value="${esc(identifier)}" placeholder="+7 900-000-00-02 или name@example.ru" oninput="if(/\d/.test(this.value)) formatPhoneInput(this)"></label><div class="actions"><button class="btn primary" onclick="recoverAccount()">Восстановить аккаунт</button></div><div class="item" style="background:var(--surface2)">Сейчас код не отправляется. На следующем этапе подключим одноразовый код на подтверждённый телефон или e-mail.</div></div></div>`}
async function login(){authError='';try{let x=await rawAuth('/api/v1/auth/login/',{identifier:document.getElementById('loginIdentifier').value,password:document.getElementById('loginPassword').value});token=x.token;sessionStorage.setItem('dobrosmena_token',token);data.user=x.user;role=x.user.role;closeModal();await load()}catch(e){authError=(e.code==='invalid_credentials'||e.can_recover)?'Неверный пароль. Если вы забыли пароль, воспользуйтесь восстановлением аккаунта.':e.message;openAuth('login',authError)}}
function registrationErrorText(e){
  if(e.code==='account_exists') return e.message||'Аккаунт с такими данными уже существует.';
  if(e.errors && typeof e.errors==='object'){
    const labels={last_name:'Фамилия',first_name:'Имя',middle_name:'Отчество',phone:'Номер телефона',email:'Электронная почта',password:'Пароль',role:'Тип аккаунта'};
    const lines=[];
    Object.entries(e.errors).forEach(([field,value])=>{
      const messages=Array.isArray(value)?value:[value];
      messages.forEach(msg=>lines.push(`<b>${esc(labels[field]||field)}:</b> ${esc(String(msg))}`));
    });
    if(lines.length) return lines.join('<br>');
  }
  return esc(e.message||'Не удалось создать аккаунт. Попробуйте ещё раз.');
}
function showRegistrationSuccess(user){
  const name=[user?.first_name,user?.middle_name].filter(Boolean).join(' ')||'пользователь';
  document.getElementById('modal').innerHTML=`<div class="modalbg"><div class="modal recovery-modal success-modal"><div class="success-icon">✓</div><span class="pill ok">Регистрация завершена</span><h2>Аккаунт успешно создан</h2><p>Добро пожаловать, <b>${esc(name)}</b>!</p><p class="muted">Ваш аккаунт зарегистрирован. Вы уже вошли в систему и можете перейти в личный кабинет.</p><div class="item" style="background:var(--ok-bg)"><b>Роль:</b> ${esc(roleLabel(user?.role))}<br><b>Телефон:</b> ${esc(user?.phone||'—')}<br><b>E-mail:</b> ${esc(user?.email||'—')}</div><div class="actions"><button class="btn primary" onclick="closeModal();load()">Перейти в личный кабинет</button><button class="btn" onclick="closeModal();renderPublicHome()">Остаться на главной</button></div></div></div>`;
}
async function register(){
  const button=document.querySelector('.auth-register-submit');
  if(button){button.disabled=true;button.textContent='Создаём аккаунт…'}
  try{
    let x=await rawAuth('/api/v1/auth/register/',{last_name:$('#regLastName').value,first_name:$('#regFirstName').value,middle_name:$('#regMiddleName').value,phone:$('#regPhone').value,email:$('#regEmail').value,password:$('#regPassword').value,role:window.regRole||'customer'});
    token=x.token;sessionStorage.setItem('dobrosmena_token',token);data.user=x.user;role=x.user.role;showRegistrationSuccess(x.user);
  }catch(e){
    if(e.code==='account_exists') openDuplicateAccount(e.message,e.field);
    else openAuth('register',registrationErrorText(e));
  }finally{
    const b=document.querySelector('.auth-register-submit');if(b){b.disabled=false;b.textContent='Зарегистрироваться'}
  }
}
async function rawAuth(url,body){
  let r;
  try{r=await fetch(url,{method:'POST',headers:{'Content-Type':'application/json'},body:JSON.stringify(body)})}
  catch(networkError){throw Object.assign(Error('Не удалось связаться с сервером. Проверьте, запущен ли Docker и доступен ли сайт.'),{code:'network_error'})}
  let x={};try{x=await r.json()}catch(e){}
  if(!r.ok){
    const first=x.detail||x.message||x.non_field_errors?.[0];
    const fallback=Object.values(x).flat?.()?.[0]||'Ошибка при выполнении запроса.';
    let err=Error(first||fallback);Object.assign(err,x,{errors:x});throw err
  }
  return x
}
async function demoLogin(phone){openAuth('login');setTimeout(()=>{let i=$('#loginIdentifier'),p=$('#loginPassword');if(i)i.value=phone;if(p)p.value='Dobrosmena123!';login()},50)}
function openDuplicateAccount(message,field){document.getElementById('modal').innerHTML=`<div class="modalbg"><div class="modal recovery-modal"><span class="pill danger">Аккаунт уже существует</span><h2>Регистрация не выполнена</h2><p>${esc(message||'Аккаунт с такими данными уже создан.')}</p><div class="item" style="background:var(--warnbg)">Проверьте ${field==='email'?'электронную почту':'номер телефона'} или войдите в существующий аккаунт.</div><div class="actions"><button class="btn primary" onclick="closeModal();openAuth('login')">Войти</button><button class="btn" onclick="closeModal();openAuth('register')">Изменить данные</button><button class="btn" onclick="openRecovery($('#reg${field==='email'?'Email':'Phone'}')?.value||'')">Восстановить аккаунт</button></div></div></div>`}
async function recoverAccount(){try{let id=$('#recoveryIdentifier').value.trim();let x=await rawAuth('/api/v1/auth/recover/',{identifier:id});document.getElementById('modal').innerHTML=`<div class="modalbg"><div class="modal recovery-modal"><span class="eyebrow">Запрос принят</span><h2>Восстановление подготовлено</h2><p>${esc(x.message)}</p><div class="item" style="background:var(--surface2)">На следующем этапе сюда подключим одноразовый код, который будет отправляться на подтверждённый телефон или e-mail.</div><button class="btn primary" onclick="closeModal();openAuth('login')">Вернуться ко входу</button></div></div>`}catch(e){toast(e.message)}}
async function logout(){try{await api('/api/v1/auth/logout/',{method:'POST'})}catch(e){}token='';sessionStorage.removeItem('dobrosmena_token');data={};role='customer';section='dashboard';document.getElementById('publicHeader')?.remove();document.querySelector('.top')?.classList.remove('logged');document.body.insertAdjacentHTML('afterbegin',publicHeaderHtml());renderPublicHome()}
function selectRegRole(r){window.regRole=r;const a=$('#roleCustomer'),b=$('#roleCaregiver');if(a&&b){a.classList.toggle('active',r==='customer');b.classList.toggle('active',r==='caregiver')}}

function current(){return data.user||{}}
function tabs(items){return `<div class="tabs">${items.map(([id,t])=>`<button class="btn tab ${section===id?'primary':''}" onclick="go('${id}')">${t}</button>`).join('')}</div>`}
function go(s){section=s;render()}
function layout(title,sub,content,nav){return `<div class="wrap"><div class="hero"><div><span class="pill">${esc(nav)}</span><h1>${title}</h1><div class="muted">${sub}</div></div></div>${content}</div>`}
function orderCard(o,buttons=''){return `<div class="card order"><div class="row"><b>Заказ #${o.id}</b>${status(o)}</div><h3>${esc(o.recipient)}</h3><div class="muted">${dt(o.start_at)} · ${o.hours} ч · ${money(o.total)}</div><p>Исполнитель: <b>${esc(o.caregiver||'Не назначен')}</b><br>Район: ${esc(o.area)} · План ухода v${o.plan_version}</p>${o.incidents?.length?`<div class="item warn">⚠ Инцидентов: ${o.incidents.length}</div>`:''}<div class="actions">${buttons}<button class="btn" onclick="details(${o.id})">Подробнее</button></div></div>`}
function render(){document.querySelectorAll('#roles button').forEach(b=>b.classList.toggle('active',b.dataset.role===role));$('#who').textContent=current().full_name||'';if(role==='customer')customer();if(role==='caregiver')caregiver();if(role==='admin')admin()}
function customer(){let u=current(), orders=data.orders.filter(o=>o.customer_id===u.id), r=data.recipients.find(x=>x.customer_id===u.id), plans=data.plans.filter(p=>p.recipient_id===r?.id);let active=orders.filter(o=>['started','arrived','en_route'].includes(o.status));let teams=data.users.filter(x=>x.role==='caregiver');let body='';
if(section==='dashboard') body=`${tabs([['dashboard','Обзор'],['orders','Мои заказы'],['recipients','Получатели'],['plan','План ухода'],['team','Команда'],['finance','Оплата и документы'],['profile','Мой профиль']])}<div class="grid"><div class="card"><div class="muted">Активные смены</div><div class="stat">${active.length}</div><div>сейчас</div></div><div class="card"><div class="muted">Предстоящие</div><div class="stat">${orders.filter(o=>o.status!=='completed').length}</div><div>заказов</div></div><div class="card"><div class="muted">Получатель</div><div class="stat">1</div><div>${esc(r?.full_name||'—')}</div></div><div class="card"><div class="muted">Версия плана</div><div class="stat">v${plans.at(-1)?.version||1}</div><div>активная</div></div></div><div class="grid2" style="margin-top:16px"><div class="card"><h2>Ближайшая смена</h2>${orders.length?orderCard(orders[0],`<button class="btn primary" onclick="details(${orders[0].id})">Открыть смену</button><button class="btn" onclick="replace(${orders[0].id})">Запросить замену</button>`):'<div class="empty">Нет заказов</div>'}</div><div class="card"><h2>Быстрые действия</h2><div class="actions"><button class="btn primary" onclick="newOrder()">+ Создать заказ</button><button class="btn" onclick="go('plan')">Изменить план ухода</button><button class="btn" onclick="go('team')">Управление командой</button></div></div></div>`;
if(section==='orders') body=`${tabs([['dashboard','Обзор'],['orders','Мои заказы'],['recipients','Получатели'],['plan','План ухода'],['team','Команда'],['finance','Оплата и документы'],['profile','Мой профиль']])}<div class="card"><div class="bar"><h2>Все заказы</h2><button class="btn primary" onclick="newOrder()">+ Новый заказ</button></div>${orders.map(o=>orderCard(o,`<button class="btn" onclick="replace(${o.id})">Замена</button>`)).join('')||'<div class="empty">Заказов пока нет</div>'}</div>`;
if(section==='recipients') body=`${tabs([['dashboard','Обзор'],['orders','Мои заказы'],['recipients','Получатели'],['plan','План ухода'],['team','Команда'],['finance','Оплата и документы'],['profile','Мой профиль']])}<div class="grid2"><div class="card"><h2>${esc(r?.full_name)}</h2><p>Год рождения: ${r?.birth_year||'—'}</p><p>Согласие получателя: ${r?.consent_confirmed?'✓ подтверждено':'не подтверждено'}</p><p>${esc(r?.notes)}</p></div><div class="card"><h2>Контакты семьи</h2><div class="item">${esc(u.full_name)} · основной заказчик<br>${esc(u.phone)}</div></div></div>`;
if(section==='plan') body=`${tabs([['dashboard','Обзор'],['orders','Мои заказы'],['recipients','Получатели'],['plan','План ухода'],['team','Команда'],['finance','Оплата и документы'],['profile','Мой профиль']])}<div class="card"><div class="bar"><h2>План ухода — ${esc(r?.full_name)}</h2><span class="pill">v${plans.at(-1)?.version||1} · активен</span></div><div class="grid3"><div><h3>Задачи</h3>${(plans.at(-1)?.tasks||[]).map(x=>`<div class="item">✓ ${esc(x)}</div>`).join('')}</div><div><h3>Нельзя</h3>${(plans.at(-1)?.prohibitions||[]).map(x=>`<div class="item warn">⚠ ${esc(x)}</div>`).join('')}</div><div><h3>Предпочтения</h3>${(plans.at(-1)?.preferences||[]).map(x=>`<div class="item info">${esc(x)}</div>`).join('')}</div></div><hr><h3>История версий</h3>${plans.map(p=>`<div class="item"><b>v${p.version}</b> · ${p.status} · ${dt(p.created_at)}</div>`).join('')}</div>`;
if(section==='team') body=`${tabs([['dashboard','Обзор'],['orders','Мои заказы'],['recipients','Получатели'],['plan','План ухода'],['team','Команда'],['finance','Оплата и документы'],['profile','Мой профиль']])}<div class="grid3">${teams.map((x,i)=>`<div class="card"><h2>${esc(x.full_name)}</h2><span class="pill">✓ Проверен</span><p>★★★★★ 4.${i?8:9} · ${i?31:87} смен</p><p>Деменция ✓<br>Маломобильные ✓<br>Гигиена ✓</p><button class="btn" onclick="profile(${x.id})">Профиль</button></div>`).join('')}</div>`;
if(section==='finance') body=`${tabs([['dashboard','Обзор'],['orders','Мои заказы'],['recipients','Получатели'],['plan','План ухода'],['team','Команда'],['finance','Оплата и документы'],['profile','Мой профиль']])}<div class="grid3"><div class="card"><h2>Оплата</h2><p>Демо-оплата хранится отдельно от статуса заказа.</p><button class="btn primary">Добавить способ оплаты</button></div><div class="card"><h2>Расходы</h2><div class="stat">${money(orders.reduce((a,o)=>a+o.total,0))}</div><div>стоимость заказов</div></div><div class="card"><h2>Документы</h2><p>Квитанции и история возвратов будут здесь.</p></div></div>`;

if(section==='profile') body=`${tabs([['dashboard','Обзор'],['orders','Мои заказы'],['recipients','Получатели'],['plan','План ухода'],['team','Команда'],['finance','Оплата и документы'],['profile','Мой профиль']])}<div class="profile-shell"><div class="profile-cover"><div class="profile-avatar ${u.avatar_url?'has-image':''}" ${u.avatar_url?`style="background-image:url('${esc(u.avatar_url)}')"`:''}>${u.avatar_url?'':esc((u.first_name||u.last_name||'Д').slice(0,1).toUpperCase())}</div><div><span class="pill">Заказчик</span><h2>${esc(u.first_name)} ${esc(u.middle_name)}</h2><p>Ваши контактные данные и настройки аккаунта.</p></div><button class="btn primary" onclick="openProfileEditor()">Редактировать профиль</button></div><div class="profile-grid"><div class="card"><h3>Контактные данные</h3><div class="profile-field"><span>Фамилия</span><b>${esc(u.last_name)}</b></div><div class="profile-field"><span>Имя и отчество</span><b>${esc([u.first_name,u.middle_name].filter(Boolean).join(' '))}</b></div><div class="profile-field"><span>Телефон</span><b>${esc(u.phone)}</b></div><div class="profile-field"><span>E-mail</span><b>${esc(u.email||'—')}</b></div></div><div class="card"><h3>Фотография</h3><p>Фото помогает членам семьи и команде быстрее узнавать участника сервиса.</p><button class="btn" style="margin-top:16px" onclick="openProfileEditor()">Добавить или изменить фото</button></div></div></div>`;
$('#app').innerHTML=layout(`Личный кабинет заказчика`, `Здравствуйте, ${esc([u.first_name, u.middle_name].filter(Boolean).join(' '))}. Здесь вы управляете уходом близкого человека.`,body,'ЗАКАЗЧИК')}
function caregiver(){let u=current(), orders=data.orders.filter(o=>o.caregiver_id===u.id), offers=data.orders.filter(o=>!o.caregiver_id&&['matching','replacement'].includes(o.status));let body='';
if(section==='dashboard') body=`${tabs([['dashboard','Обзор'],['shifts','Мои смены'],['offers','Предложения'],['calendar','Календарь'],['income','Доход'],['profile','Мой профиль']])}<div class="grid"><div class="card"><div class="muted">Смен</div><div class="stat">${orders.length}</div><div>в демо</div></div><div class="card"><div class="muted">Часов</div><div class="stat">${orders.reduce((a,o)=>a+o.hours,0)}</div><div>запланировано</div></div><div class="card"><div class="muted">Начислено</div><div class="stat">${money(orders.reduce((a,o)=>a+o.caregiver_amount,0))}</div><div>до налога</div></div><div class="card"><div class="muted">Проверка</div><div class="stat">✓</div><div>актуальна</div></div></div><div class="grid2" style="margin-top:16px"><div class="card"><h2>Ближайшая смена</h2>${orders.length?orderCard(orders[0],`<button class="btn primary" onclick="careStart(${orders[0].id})">Открыть смену</button>`):'<div class="empty">Нет смен</div>'}</div><div class="card"><h2>Новые предложения</h2>${offers.map(o=>orderCard(o,`<button class="btn primary" onclick="accept(${o.id})">Принять</button>`)).join('')||'<div class="empty">Нет предложений</div>'}</div></div>`;
if(section==='shifts') body=`${tabs([['dashboard','Обзор'],['shifts','Мои смены'],['offers','Предложения'],['calendar','Календарь'],['income','Доход'],['profile','Мой профиль']])}<div class="card"><h2>Мои смены</h2>${orders.map(o=>orderCard(o,`<button class="btn primary" onclick="careStart(${o.id})">${o.status==='started'?'Смена идёт':'Начать'}</button><button class="btn" onclick="report(${o.id})">Отчёт</button>`)).join('')||'<div class="empty">Нет смен</div>'}</div>`;
if(section==='offers') body=`${tabs([['dashboard','Обзор'],['shifts','Мои смены'],['offers','Предложения'],['calendar','Календарь'],['income','Доход'],['profile','Мой профиль']])}<div class="card"><h2>Предложения</h2>${offers.map(o=>orderCard(o,`<button class="btn primary" onclick="accept(${o.id})">Принять смену</button>`)).join('')||'<div class="empty">Новых предложений нет</div>'}</div>`;
if(section==='calendar') body=`${tabs([['dashboard','Обзор'],['shifts','Мои смены'],['offers','Предложения'],['calendar','Календарь'],['income','Доход'],['profile','Мой профиль']])}<div class="card"><h2>Календарь доступности</h2>${orders.map(o=>`<div class="item"><b>${dt(o.start_at)}</b> · ${o.hours} ч · ${esc(o.recipient)} ${status(o)}</div>`).join('')}</div>`;
if(section==='income') body=`${tabs([['dashboard','Обзор'],['shifts','Мои смены'],['offers','Предложения'],['calendar','Календарь'],['income','Доход'],['profile','Мой профиль']])}<div class="grid3"><div class="card"><h2>Стоимость услуг</h2><div class="stat">${money(orders.reduce((a,o)=>a+o.total,0))}</div></div><div class="card"><h2>Комиссия 18%</h2><div class="stat">-${money(orders.reduce((a,o)=>a+o.commission,0))}</div></div><div class="card"><h2>Начислено</h2><div class="stat">${money(orders.reduce((a,o)=>a+o.caregiver_amount,0))}</div><div>до налога</div></div></div><div class="card" style="margin-top:16px"><h2>История</h2><table class="table"><tr><th>Заказ</th><th>Дата</th><th>Услуга</th><th>Начислено</th></tr>${orders.map(o=>`<tr><td>#${o.id}</td><td>${dt(o.start_at)}</td><td>${o.hours} ч × ${money(o.rate)}</td><td>${money(o.caregiver_amount)}</td></tr>`).join('')}</table></div>`;
if(section==='profile') body=`${tabs([['dashboard','Обзор'],['shifts','Мои смены'],['offers','Предложения'],['calendar','Календарь'],['income','Доход'],['profile','Мой профиль']])}<div class="profile-shell"><div class="profile-cover"><div class="profile-avatar ${u.avatar_url?'has-image':''}" ${u.avatar_url?`style="background-image:url('${esc(u.avatar_url)}')"`:''}>${u.avatar_url?'':esc((u.first_name||u.last_name||'И').slice(0,1).toUpperCase())}</div><div><span class="pill ok">Исполнитель</span><h2>${esc(u.first_name)} ${esc(u.middle_name)}</h2><p>${u.experience_years||0} лет опыта · профиль помогает подобрать подходящие смены</p></div><button class="btn primary" onclick="openProfileEditor()">Редактировать профиль</button></div><div class="profile-grid"><div class="card"><div class="bar"><h3>Мои сильные стороны</h3><span class="pill">${(u.skills||[]).length} выбрано</span></div><div class="skill-chips">${skillLabels(u.skills).map(x=>`<span class="skill-chip">✓ ${esc(x)}</span>`).join('')||'<span class="muted">Добавьте навыки, чтобы заказчику было проще понять, подойдёте ли вы.</span>'}</div><h3 style="margin-top:24px">О себе</h3><p class="profile-about">${esc(u.about||'Расскажите немного о себе, опыте и формате помощи, который вам комфортен.')}</p></div><div class="card"><h3>Условия работы</h3><div class="profile-criteria">${preferenceRows(u.work_preferences)}</div><div class="item info" style="margin-top:16px">Заказчик увидит эти критерии при подборе. Они помогают сравнивать исполнителей по конкретному запросу, а не только по рейтингу.</div></div></div></div>`;

$('#app').innerHTML=layout('Личный кабинет исполнителя','Смены, предложения, календарь и прозрачный расчёт дохода.',body,'ИСПОЛНИТЕЛЬ')}
function admin(){
let orders=data.orders||[], incidents=data.incidents||[], users=data.users||[], body='';
const nav=[['dashboard','Операционный центр'],['users','Пользователи'],['orders','Заказы'],['matching','Подбор'],['shifts','Смены'],['caregivers','Исполнители'],['incidents','Инциденты'],['finance','Финансы'],['audit','Аудит']];
const customers=users.filter(x=>x.role==='customer'), caregivers=users.filter(x=>x.role==='caregiver'), admins=users.filter(x=>x.role==='admin');
const navHtml=()=>tabs(nav)+adminSearchHtml();
if(section==='dashboard') body=`${navHtml()}<div class="grid"><div class="card"><div class="muted">Заказчики</div><div class="stat">${customers.length}</div><div>зарегистрировано</div></div><div class="card"><div class="muted">Исполнители</div><div class="stat">${caregivers.length}</div><div>зарегистрировано</div></div><div class="card"><div class="muted">Всего пользователей</div><div class="stat">${users.length}</div><div>в системе</div></div><div class="card"><div class="muted">Активные аккаунты</div><div class="stat">${users.filter(x=>x.is_active).length}</div><div>доступ разрешён</div></div></div><div class="grid"><div class="card"><div class="muted">Новые / на подборе</div><div class="stat">${orders.filter(o=>['draft','risk_check','matching','caregiver_requested','replacement'].includes(o.status)).length}</div></div><div class="card"><div class="muted">Активные смены</div><div class="stat">${orders.filter(o=>['accepted','payment_authorized','confirmed','en_route','arrived','started'].includes(o.status)).length}</div></div><div class="card"><div class="muted">Инциденты</div><div class="stat">${incidents.filter(i=>!i.resolved).length}</div></div><div class="card"><div class="muted">GMV</div><div class="stat">${money(orders.reduce((a,o)=>a+o.total,0))}</div></div></div><div class="grid2" style="margin-top:16px"><div class="card"><h2>Последние регистрации</h2>${[...users].sort((a,b)=>new Date(b.created_at)-new Date(a.created_at)).slice(0,8).map(u=>`<div class="item"><div class="bar"><b>${esc(u.full_name)}</b><span class="pill">${esc(roleLabel(u.role))}</span></div><div class="muted">${esc(u.phone)} · ${esc(u.email||'—')}</div><small>Регистрация: ${dt(u.created_at)}</small><br><button class="btn" onclick="userDetails(${u.id})">Открыть карточку</button></div>`).join('')||'<div class="empty">Пользователей пока нет</div>'}</div><div class="card"><h2>Оперативная очередь</h2>${orders.slice(0,6).map(o=>orderCard(o,`<button class="btn primary" onclick="details(${o.id})">Открыть</button><button class="btn" onclick="assign(${o.id})">${o.caregiver?'Сменить':'Назначить'}</button>`)).join('')||'<div class="empty">Заказов пока нет</div>'}</div></div>`;
if(section==='users') body=`${navHtml()}<div class="grid3"><div class="card"><div class="muted">Заказчики</div><div class="stat">${customers.length}</div></div><div class="card"><div class="muted">Исполнители</div><div class="stat">${caregivers.length}</div></div><div class="card"><div class="muted">Администраторы</div><div class="stat">${admins.length}</div></div></div><div class="card" style="margin-top:16px"><h2>Все пользователи</h2><div class="muted" style="margin-bottom:12px">Администратор видит регистрационные данные, статус аккаунта, дату регистрации и последнего входа. Пароли и токены намеренно не отображаются.</div><table class="table"><tr><th>ID</th><th>ФИО</th><th>Роль</th><th>Телефон</th><th>E-mail</th><th>Регистрация</th><th>Последний вход</th><th>Статус</th><th></th></tr>${[...users].sort((a,b)=>new Date(b.created_at)-new Date(a.created_at)).map(u=>`<tr><td>#${u.id}</td><td><b>${esc(u.full_name)}</b></td><td>${esc(roleLabel(u.role))}</td><td>${esc(u.phone)}</td><td>${esc(u.email||'—')}</td><td>${dt(u.created_at)}</td><td>${u.last_login?dt(u.last_login):'—'}</td><td>${u.is_active?'<span class="pill">Активен</span>':'<span class="pill danger">Заблокирован</span>'} ${u.is_verified?'<span class="pill">Проверен</span>':'<span class="pill">Не проверен</span>'}</td><td><button class="btn" onclick="userDetails(${u.id})">Карточка</button></td></tr>`).join('')}</table></div>`;
if(section==='orders') body=`${navHtml()}<div class="card"><h2>Все заказы</h2><table class="table"><tr><th>ID</th><th>Заказчик</th><th>Получатель</th><th>Исполнитель</th><th>Время</th><th>Статус</th><th>Сумма</th><th></th></tr>${orders.map(o=>`<tr><td>#${o.id}</td><td>${esc(o.customer)}</td><td>${esc(o.recipient)}</td><td>${esc(o.caregiver||'—')}</td><td>${dt(o.start_at)}</td><td>${status(o)}</td><td>${money(o.total)}</td><td><button class="btn" onclick="details(${o.id})">Открыть</button></td></tr>`).join('')}</table></div>`;
if(section==='matching') body=`${navHtml()}<div class="card"><h2>Центр подбора</h2>${orders.filter(o=>['matching','replacement','draft','risk_check','caregiver_requested'].includes(o.status)).map(o=>`<div class="item"><div class="bar"><b>#${o.id} · ${esc(o.recipient)}</b>${status(o)}</div><p>${dt(o.start_at)} · ${o.hours} ч · ${esc(o.area)}</p><div class="grid3">${caregivers.map((c,i)=>`<div class="item"><b>${esc(c.full_name)}</b><br><span class="pill">${Math.max(70,98-i*4)}% соответствие</span><br><small>доступность ✓ · район ✓ · профиль ✓</small><br><button class="btn primary" onclick="assignTo(${o.id},${c.id})">Предложить</button></div>`).join('')}</div></div>`).join('')||'<div class="empty">Очередь подбора пуста</div>'}</div>`;
if(section==='shifts') body=`${navHtml()}<div class="card"><h2>Диспетчерский календарь</h2>${orders.map(o=>`<div class="item"><div class="bar"><b>${dt(o.start_at)} — ${esc(o.recipient)}</b>${status(o)}</div><div>${esc(o.caregiver||'Нет исполнителя')} · ${o.hours} ч · ${money(o.total)}</div></div>`).join('')||'<div class="empty">Смен нет</div>'}</div>`;
if(section==='caregivers') body=`${navHtml()}<div class="grid3">${caregivers.map(c=>`<div class="card"><h2>${esc(c.full_name)}</h2><span class="pill">${c.is_verified?'✓ Проверен':'Не проверен'}</span><p>${esc(c.phone)}</p><p>${esc(c.email||'—')}</p><p>Регистрация: ${dt(c.created_at)}</p><p>Последний вход: ${c.last_login?dt(c.last_login):'—'}</p><button class="btn primary" onclick="userDetails(${c.id})">Полная карточка</button></div>`).join('')||'<div class="empty">Исполнителей пока нет</div>'}</div>`;
if(section==='incidents') body=`${navHtml()}<div class="card"><h2>Центр инцидентов</h2>${incidents.map(i=>`<div class="item ${i.resolved?'':'warn'}"><div class="bar"><b>#${i.order_id} · ${esc(i.severity)}</b><span>${i.resolved?'Закрыт':'Требует внимания'}</span></div><p>${esc(i.text)}</p><button class="btn" onclick="resolveIncident(${i.id})">${i.resolved?'Открыть':'Закрыть инцидент'}</button></div>`).join('')||'<div class="empty">Инцидентов нет</div>'}</div>`;
if(section==='finance') body=`${navHtml()}<div class="grid3"><div class="card"><h2>GMV</h2><div class="stat">${money(orders.reduce((a,o)=>a+o.total,0))}</div></div><div class="card"><h2>Комиссия</h2><div class="stat">${money(orders.reduce((a,o)=>a+o.commission,0))}</div><div>18% гипотеза</div></div><div class="card"><h2>Исполнителям</h2><div class="stat">${money(orders.reduce((a,o)=>a+o.caregiver_amount,0))}</div></div></div><div class="card" style="margin-top:16px"><h2>Финансовая лента</h2><table class="table"><tr><th>Заказ</th><th>Заказчик</th><th>GMV</th><th>Комиссия</th><th>Исполнителю</th></tr>${orders.map(o=>`<tr><td>#${o.id}</td><td>${esc(o.customer)}</td><td>${money(o.total)}</td><td>${money(o.commission)}</td><td>${money(o.caregiver_amount)}</td></tr>`).join('')}</table></div>`;
if(section==='audit') body=`${navHtml()}<div class="card"><h2>Журнал действий</h2><div class="timeline">${(data.audit||[]).map(a=>`<div class="event"><b>${esc(a.action)}</b><span class="muted">${dt(a.created_at)} · ${esc(a.actor)}</span><div>${esc(a.entity_type)} #${a.entity_id}</div></div>`).join('')||'<div class="empty">Журнал пуст</div>'}</div></div>`;
$('#app').innerHTML=layout('Административный центр','Полный контроль пользователей, заказов, смен, подбора, инцидентов, финансов и аудита.',body,'АДМИНИСТРАТОР')}
async function assign(id){let c=data.users.find(x=>x.role==='caregiver');return assignTo(id,c.id)}
async function assignTo(id,cid){await api(`/api/v1/orders/${id}/assign/`,{method:'POST',body:JSON.stringify({caregiver_id:cid})});toast('Исполнитель назначен');await load()}
async function accept(id){await api(`/api/v1/orders/${id}/accept/`,{method:'POST'});toast('Смена принята');await load()}
async function careStart(id){await api(`/api/v1/orders/${id}/start/`,{method:'POST'});toast('Смена начата');await load()}
async function replace(id){await api(`/api/v1/orders/${id}/replace/`,{method:'POST'});toast('Запущен процесс замены');await load()}
async function report(id){let c=prompt('Комментарий к смене','Состояние без изменений. План выполнен.');if(c!==null){await api(`/api/v1/orders/${id}/report/`,{method:'POST',body:JSON.stringify({comment:c,tasks_done:['Завтрак','Прогулка','Гигиена'],condition:'no_change'})});toast('Отчёт сохранён');await load()}}
async function resolveIncident(id){await api(`/api/v1/incidents/${id}/resolve/`,{method:'POST'});toast('Статус инцидента изменён');await load()}
function details(id){let o=data.orders.find(x=>x.id===id);let r=data.recipients.find(x=>x.id===o.recipient_id);let p=data.plans.find(x=>x.id===o.plan_id);$('#modal').innerHTML=`<div class="modalbg" onclick="if(event.target===this)closeModal()"><div class="modal"><button class="btn close" onclick="closeModal()">Закрыть</button><h2>Заказ #${o.id}</h2><p>${status(o)} · ${dt(o.start_at)} — ${dt(o.end_at)}</p><div class="grid2"><div><h3>Участники</h3><div class="item">Заказчик: ${esc(o.customer)}</div><div class="item">Получатель: ${esc(o.recipient)}</div><div class="item">Исполнитель: ${esc(o.caregiver||'Не назначен')}</div><h3>Адрес</h3><div class="item">${esc(o.address)}<br><small>${esc(o.area)}</small></div></div><div><h3>План ухода v${o.plan_version}</h3><div class="item"><b>Задачи</b><br>${(p?.tasks||[]).join(' · ')}</div><div class="item warn"><b>Запреты</b><br>${(p?.prohibitions||[]).join('<br>')}</div><h3>Финансы</h3><div class="item">${money(o.total)} · комиссия ${money(o.commission)} · исполнителю ${money(o.caregiver_amount)}</div></div></div><h3>События</h3><div class="timeline">${(data.audit||[]).filter(a=>a.entity_id===o.id&&a.entity_type==='Order').map(a=>`<div class="event"><b>${esc(a.action)}</b><span class="muted">${dt(a.created_at)} · ${esc(a.actor)}</span></div>`).join('')||'История пока пуста'}</div></div></div>`}
async function userDetails(id){
 try{
  const x=await api(`/api/v1/admin/users/${id}/`), u=x.user, st=x.stats||{};
  const recipients=x.recipients||[], customerOrders=x.customer_orders||[], caregiverOrders=x.caregiver_orders||[], logs=x.audit||[];
  const recipientHtml=recipients.map(r=>`<div class="item"><b>${esc(r.full_name)}</b> · ${r.birth_year||'—'} г.р. · согласие: ${r.consent_confirmed?'да':'нет'}<br><small>${esc(r.notes||'')}</small></div>`).join('')||'<div class="empty">Получателей нет</div>';
  const customerOrderHtml=customerOrders.slice(0,20).map(o=>`<div class="event"><b>#${o.id} · ${esc(o.recipient)}</b><span class="muted">${dt(o.created_at||o.start_at)}</span><div>${status(o)} · ${money(o.total)}</div></div>`).join('');
  const caregiverOrderHtml=caregiverOrders.slice(0,20).map(o=>`<div class="event"><b>#${o.id} · ${esc(o.recipient)}</b><span class="muted">${dt(o.start_at)}</span><div>${status(o)} · ${o.hours} ч · ${money(o.caregiver_amount)}</div></div>`).join('');
  const logHtml=logs.slice(0,20).map(a=>`<div class="event"><b>${esc(a.action)}</b><span class="muted">${dt(a.created_at)}</span><div>${esc(a.entity_type)} #${a.entity_id}</div></div>`).join('')||'<div class="empty">Действий пока нет</div>';
  const recipientSection=u.role==='customer'?`<h3>Получатели</h3>${recipientHtml}`:'';
  const customerOrdersSection=customerOrders.length?`<h3>Заказы пользователя</h3><div class="timeline">${customerOrderHtml}</div>`:'';
  const caregiverOrdersSection=caregiverOrders.length?`<h3>Смены исполнителя</h3><div class="timeline">${caregiverOrderHtml}</div>`:'';
  $('#modal').innerHTML=`<div class="modalbg" onclick="if(event.target===this)closeModal()"><div class="modal" style="max-width:1050px"><button class="btn close" onclick="closeModal()">Закрыть</button><span class="pill">${esc(roleLabel(u.role))}</span><h2>${esc(u.full_name)}</h2><div class="grid3"><div class="item"><b>Телефон</b><br>${esc(u.phone)}</div><div class="item"><b>E-mail</b><br>${esc(u.email||'—')}</div><div class="item"><b>Статус</b><br>${u.is_active?'Активен':'Заблокирован'} · ${u.is_verified?'Проверен':'Не проверен'}</div><div class="item"><b>Регистрация</b><br>${dt(u.created_at)}</div><div class="item"><b>Последний вход</b><br>${u.last_login?dt(u.last_login):'—'}</div><div class="item"><b>ID аккаунта</b><br>#${u.id}</div></div><div class="grid3" style="margin-top:16px"><div class="card"><div class="muted">Заказы как заказчик</div><div class="stat">${st.customer_orders||0}</div></div><div class="card"><div class="muted">Смены как исполнитель</div><div class="stat">${st.caregiver_orders||0}</div></div><div class="card"><div class="muted">Завершено</div><div class="stat">${st.completed_orders||0}</div></div></div>${recipientSection}${customerOrdersSection}${caregiverOrdersSection}<h3>Действия пользователя</h3><div class="timeline">${logHtml}</div><div class="item info small" style="margin-top:16px">Пароли, токены авторизации и другие секреты администраторам не показываются.</div></div></div>`;
 }catch(e){toast(e.message)}
}
function profile(id){userDetails(id)}

const PROFILE_SKILLS=[
 ['meal_preparation','Приготовление еды'],['shopping','Покупки и бытовые поручения'],['household_help','Помощь по дому'],['walks','Прогулки и сопровождение'],['companionship','Спокойное общение и компания'],['personal_hygiene','Помощь с личной гигиеной'],['mobility_support','Поддержка при передвижении'],['dementia','Сопровождение людей с деменцией'],['memory_support','Поддержка при нарушениях памяти'],['light_exercise','Лёгкая физическая активность'],['night_work','Готовность к ночным сменам'],['weekend_work','Работа по выходным'],['live_in','Проживание у получателя'],['hospital_accompaniment','Сопровождение в больнице'],['transport','Сопровождение на автомобиле'],['pets','Уход за домашними животными'],['family_communication','Связь и взаимодействие с семьёй'],['reporting','Короткие отчёты после смены'],['calm_communication','Спокойное и бережное общение'],['appointment_accompaniment','Сопровождение на приём']
];
function skillLabel(id){return PROFILE_SKILLS.find(x=>x[0]===id)?.[1]||id}
function skillLabels(ids){return (ids||[]).map(skillLabel)}
function preferenceRows(p={}){const rows=[['night_work','Ночные смены','Готовность работать ночью'],['weekend_work','Выходные','Готовность брать смены в выходные'],['live_in','Проживание','Готовность к длительному проживанию'],['hospital_accompaniment','Больница','Готовность сопровождать в больнице'],['transport','Автомобиль','Есть возможность сопровождения на автомобиле']];return rows.map(([k,t,d])=>`<div class="criterion-row"><div><b>${t}</b><span>${d}</span></div><span class="pill ${p[k]?'ok':''}">${p[k]?'Да':'Нет'}</span></div>`).join('')}
function openProfileEditor(){const u=current(), caregiverRole=u.role==='caregiver';const checked=new Set(u.skills||[]);document.getElementById('modal').innerHTML=`<div class="modalbg" onclick="if(event.target===this)closeModal()"><div class="modal profile-modal"><button class="close" onclick="closeModal()">Закрыть</button><span class="eyebrow">Настройки профиля</span><h2>Редактирование профиля</h2><p class="muted">Изменения сохраняются в аккаунте и используются для подбора и связи.</p><form id="profileForm" onsubmit="saveProfile(event)"><div class="profile-edit-top"><div id="avatarPreview" class="profile-avatar edit ${u.avatar_url?'has-image':''}" ${u.avatar_url?`style="background-image:url('${esc(u.avatar_url)}')"`:''}>${u.avatar_url?'':esc((u.first_name||'Д').slice(0,1).toUpperCase())}</div><label class="file-btn">Выбрать фотографию<input id="profileAvatar" type="file" accept="image/jpeg,image/png,image/webp" onchange="previewAvatar(this)"></label><span class="muted small">JPG, PNG или WebP · до 5 МБ</span></div><div class="grid2"><label>Фамилия<input id="profileLastName" class="input" value="${esc(u.last_name)}" required></label><label>Имя<input id="profileFirstName" class="input" value="${esc(u.first_name)}" required></label><label>Отчество<input id="profileMiddleName" class="input" value="${esc(u.middle_name)}" required></label><label>Телефон<input id="profilePhone" class="input" value="${esc(u.phone)}" oninput="formatPhoneInput(this)" required></label><label>E-mail<input id="profileEmail" class="input" type="email" value="${esc(u.email||'')}" required></label>${caregiverRole?`<label>Опыт работы, лет<input id="profileExperience" class="input" type="number" min="0" max="60" value="${u.experience_years||0}"></label>`:''}</div>${caregiverRole?`<div class="profile-edit-section"><div class="bar"><div><h3>Навыки и формат помощи</h3><p class="muted small">Выберите всё, что действительно готовы выполнять.</p></div><span id="skillCount" class="pill">${checked.size} выбрано</span></div><div class="skill-picker">${PROFILE_SKILLS.map(([id,label])=>`<label class="skill-option"><input type="checkbox" value="${id}" ${checked.has(id)?'checked':''} onchange="updateSkillCount()"><span>${label}</span></label>`).join('')}</div></div><div class="profile-edit-section"><h3>Дополнительные условия</h3><div class="preference-picker"><label class="toggle-option"><input id="prefNight" type="checkbox" ${u.work_preferences?.night_work?'checked':''}><span><b>Ночные смены</b><small>Готов брать смены ночью</small></span></label><label class="toggle-option"><input id="prefWeekend" type="checkbox" ${u.work_preferences?.weekend_work?'checked':''}><span><b>Выходные</b><small>Готов работать в выходные</small></span></label><label class="toggle-option"><input id="prefLiveIn" type="checkbox" ${u.work_preferences?.live_in?'checked':''}><span><b>Проживание</b><small>Готов к длительному формату</small></span></label><label class="toggle-option"><input id="prefHospital" type="checkbox" ${u.work_preferences?.hospital_accompaniment?'checked':''}><span><b>Больница</b><small>Готов сопровождать в больнице</small></span></label><label class="toggle-option"><input id="prefTransport" type="checkbox" ${u.work_preferences?.transport?'checked':''}><span><b>Автомобиль</b><small>Могу сопровождать на автомобиле</small></span></label></div></div><label>О себе<textarea id="profileAbout" class="input" rows="5" maxlength="5000" placeholder="Расскажите о своём опыте, отношении к работе, привычном формате смен и о том, что важно знать семье.">${esc(u.about||'')}</textarea><span class="muted small">До 5000 символов. Здесь можно свободно рассказать о себе — это не заменяет проверку документов и навыков.</span></label>`:''}<div class="actions"><button type="button" class="btn" onclick="closeModal()">Отмена</button><button type="submit" class="btn primary">Сохранить профиль</button></div></form></div></div>`}
function previewAvatar(input){const f=input.files?.[0];if(!f)return;if(f.size>5*1024*1024){toast('Фотография больше 5 МБ');input.value='';return}const r=new FileReader();r.onload=()=>{const x=$('#avatarPreview');x.style.backgroundImage=`url('${r.result}')`;x.classList.add('has-image');x.textContent=''};r.readAsDataURL(f)}
function updateSkillCount(){const n=document.querySelectorAll('.skill-option input:checked').length;const x=$('#skillCount');if(x)x.textContent=`${n} выбрано`}
async function saveProfile(e){e.preventDefault();const u=current(), fd=new FormData();fd.append('last_name',$('#profileLastName').value.trim());fd.append('first_name',$('#profileFirstName').value.trim());fd.append('middle_name',$('#profileMiddleName').value.trim());fd.append('phone',$('#profilePhone').value.trim());fd.append('email',$('#profileEmail').value.trim());fd.append('about',u.role==='caregiver'?$('#profileAbout').value.trim():(u.about||''));if(u.role==='caregiver'){fd.append('experience_years',$('#profileExperience').value||0);fd.append('skills',JSON.stringify([...document.querySelectorAll('.skill-option input:checked')].map(x=>x.value)));fd.append('work_preferences',JSON.stringify({night_work:$('#prefNight').checked,weekend_work:$('#prefWeekend').checked,live_in:$('#prefLiveIn').checked,hospital_accompaniment:$('#prefHospital').checked,transport:$('#prefTransport').checked}));}const f=$('#profileAvatar')?.files?.[0];if(f)fd.append('avatar',f);try{const x=await api('/api/v1/profile/',{method:'PATCH',body:fd});data.user=x.user;role=x.user.role;closeModal();toast('Профиль сохранён');render()}catch(err){toast(err.message)}}
function adminSearchHtml(){return `<div class="admin-search-wrap"><div class="admin-search-box"><span>⌕</span><input id="adminSearchInput" type="search" autocomplete="off" placeholder="Поиск: фамилия, заказ, телефон, e-mail, адрес..." oninput="adminSearchLive(this.value)" onfocus="adminSearchLive(this.value)"><button class="search-clear" onclick="clearAdminSearch()" aria-label="Очистить">×</button></div><div id="adminSearchResults" class="admin-search-results"></div><div class="muted small search-hint">Можно вводить часть фамилии, № заказа, телефон, e-mail или адрес — сервис сам определит тип совпадения.</div></div>`}
let adminSearchTimer=null;
function adminSearchLive(q){clearTimeout(adminSearchTimer);const box=$('#adminSearchResults');if(!box)return;if(q.trim().length<2){box.innerHTML='';box.classList.remove('open');return}adminSearchTimer=setTimeout(async()=>{try{const x=await api('/api/v1/admin/search/?q='+encodeURIComponent(q.trim()));box.innerHTML=x.results.length?x.results.map(r=>`<button class="search-result" onclick="openAdminSearchResult('${r.type}',${r.id})"><span class="search-result-icon">${r.type==='order'?'#':'👤'}</span><span><b>${esc(r.title)}</b><small>${esc(r.subtitle)}</small></span></button>`).join(''):'<div class="search-empty">Ничего не найдено</div>';box.classList.add('open')}catch(e){box.innerHTML='<div class="search-empty">Не удалось выполнить поиск</div>';box.classList.add('open')}},180)}
function clearAdminSearch(){const i=$('#adminSearchInput');if(i)i.value='';const b=$('#adminSearchResults');if(b){b.innerHTML='';b.classList.remove('open')}i?.focus()}
function openAdminSearchResult(type,id){const b=$('#adminSearchResults');if(b)b.classList.remove('open');if(type==='user')userDetails(id);else details(id)}
function closeModal(){$('#modal').innerHTML=''}
async function newOrder(){let r=data.recipients[0],u=current();let start=new Date(Date.now()+2*3600000);let end=new Date(start.getTime()+6*3600000);await api('/api/v1/orders/',{method:'POST',body:JSON.stringify({recipient_id:r.id,start_at:start.toISOString(),end_at:end.toISOString(),hours:6,rate:350,area:'Центральный район',address:'ул. Примерная, 15'})});toast('Новый заказ создан');section='orders';await load()}
function toast(t){let x=$('#toast');x.textContent=t;x.style.display='block';setTimeout(()=>x.style.display='none',2200)}
load();
